// canary-cry codegen -- PURE, NO IMPORTS (#608 P3; spec "Codegen and
// runtime"). The text of a run dir's generated files: playwright.config.mjs
// and one thin spec per scenario. rundir.mjs writes them and copies the
// runtime beside them.
//
// Everything a spec carries comes from the CONFIRMED manifest -- the flow in
// full, the auth flows, fixtures, egress hosts, account env var NAMES -- so
// what the browser does is exactly what the operator approved by sha, and no
// account value is ever written into a spec (SC10). The runtime reads the
// values from the env vars at run time.

/** `checkout:multi-submit:i1:spay` -> `checkout.multi-submit.i1.spay`. */
export const fileStem = (id) => id.replaceAll(':', '.');

const flowById = (manifest, id) => manifest.flows.find((f) => f.id === id);

const flowPart = (flow) => ({ id: flow.id, steps: flow.steps });

function authPart(manifest) {
  const { auth } = manifest;
  if (auth === null) return null;
  return {
    signIn: flowPart(flowById(manifest, auth.signIn)),
    signOut: flowPart(flowById(manifest, auth.signOut)),
    sessionKeys: auth.sessionKeys,
  };
}

/** The inline scenario a spec hands the runtime. */
export function scenarioPayload(manifest, scenario) {
  const flow = flowById(manifest, scenario.flow);
  return {
    id: scenario.id,
    file: fileStem(scenario.id),
    flow: scenario.flow,
    pattern: scenario.pattern,
    mayRefuse: scenario.mayRefuse === true,
    intensity: scenario.intensity,
    step: scenario.step,
    seed: manifest.seed,
    baseURL: manifest.target.baseURL,
    hosts: manifest.egressHosts,
    steps: flow.steps,
    invariants: flow.invariants ?? [],
    symptoms: flow.symptoms?.selectors ?? [],
    auth: authPart(manifest),
    accounts: manifest.accounts,
    fixtures: manifest.fixtures,
  };
}

/**
 * The env var naming one scenario's JSON report (#608 P4). The executor runs
 * each scenario as its own Playwright run, so it can checkpoint between them,
 * and points each at `results/<scenario>.json`; a standalone replay, with the
 * variable unset, writes `results.json` as before.
 */
export const RESULTS_ENV = 'CANARY_CRY_RESULTS';

// `workers: 1` because scenarios share accounts; `retries: 0` because a
// retried scenario would write twice and break its own delta. No trace,
// screenshot or video: each could capture an account value on screen.
const CONFIG_TEXT = `// Generated by canary-cry (#608). Do not edit: re-run cry to regenerate.
export default {
  testDir: './specs',
  workers: 1,
  retries: 0,
  timeout: 120000,
  outputDir: './test-results',
  reporter: [['json', { outputFile: process.env.${RESULTS_ENV} || 'results.json' }]],
  use: { headless: true, trace: 'off', screenshot: 'off', video: 'off' },
};
`;

/** The spec for one scenario: a test that hands its scenario to the runtime. */
function specText(payload, sha) {
  const json = JSON.stringify(payload, null, 2);
  return [
    `// Generated by canary-cry (#608) from manifest-sha ${sha}.`,
    '// Re-run standalone from the run dir:',
    `//   npx playwright test -c playwright.config.mjs specs/${payload.file}.spec.mjs`,
    "import { test } from '@playwright/test';",
    '',
    "import { runScenario } from '../runtime/cry-runtime.mjs';",
    '',
    `const scenario = ${json};`,
    '',
    'test(scenario.id, ({ browser }, info) =>',
    '  runScenario(browser, scenario, info),',
    ');',
    '',
  ].join('\n');
}

/**
 * Every generated file of a run dir, as `{path, text}` relative to it.
 * @param {object} manifest the confirmed manifest
 * @param {string} sha its manifest-sha
 */
export function runFiles(manifest, sha) {
  const specs = manifest.scenarios.map((s) => {
    const payload = scenarioPayload(manifest, s);
    return {
      path: `specs/${payload.file}.spec.mjs`,
      text: specText(payload, sha),
    };
  });
  return [{ path: 'playwright.config.mjs', text: CONFIG_TEXT }, ...specs];
}
